// Some portions generated by Claude
package org.eclipse.rdf4j.testsuite.query.parser.sparql.manifest;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HexFormat;
import java.util.List;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.query.Binding;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.impl.MutableTupleQueryResult;
import org.eclipse.rdf4j.rio.helpers.NTriplesUtil;

/**
 * Throw-away differential instrumentation (develop vs branch, WP9 3.11.6): writes a canonical dump of each compliance
 * test's actual result when {@code -Ddiff.dump.dir} is set. Identical copy on both sides; never merged.
 */
public final class DiffDump {

	private DiffDump() {
	}

	public static boolean enabled() {
		return System.getProperty("diff.dump.dir") != null;
	}

	static String value(Value v) {
		if (v == null) {
			return "UNDEF";
		}
		if (v instanceof BNode) {
			return "_:b";
		}
		return NTriplesUtil.toNTriplesString(v);
	}

	public static MutableTupleQueryResult tuple(Object owner, String name, String uri, TupleQueryResult result,
			boolean ordered) {
		MutableTupleQueryResult table = new MutableTupleQueryResult(result);
		if (!enabled()) {
			return table;
		}
		List<String> vars = new ArrayList<>(table.getBindingNames());
		List<String> rows = new ArrayList<>();
		while (table.hasNext()) {
			BindingSet bs = table.next();
			List<String> cells = new ArrayList<>();
			for (Binding b : bs) {
				cells.add(b.getName() + "=" + value(b.getValue()));
			}
			Collections.sort(cells);
			rows.add(String.join(" | ", cells));
		}
		table.beforeFirst();
		List<String> sorted = new ArrayList<>(rows);
		Collections.sort(sorted);
		StringBuilder sb = new StringBuilder();
		sb.append("TUPLE vars=").append(vars.stream().sorted().toList()).append(" rows=").append(rows.size())
				.append('\n');
		for (String r : sorted) {
			sb.append(r).append('\n');
		}
		if (ordered) {
			sb.append("ORDERED\n");
			for (String r : rows) {
				sb.append(r).append('\n');
			}
		}
		append(owner, name, uri, sb.toString());
		return table;
	}

	public static void graph(Object owner, String name, String uri, String label, Collection<Statement> statements) {
		if (!enabled()) {
			return;
		}
		List<String> lines = new ArrayList<>();
		for (Statement st : statements) {
			lines.add(value(st.getSubject()) + " " + value(st.getPredicate()) + " " + value(st.getObject()) + " "
					+ value(st.getContext()));
		}
		Collections.sort(lines);
		StringBuilder sb = new StringBuilder();
		sb.append("GRAPH ").append(label).append(" size=").append(lines.size()).append('\n');
		for (String l : lines) {
			sb.append(l).append('\n');
		}
		append(owner, name, uri, sb.toString());
	}

	public static void bool(Object owner, String name, String uri, boolean value) {
		if (enabled()) {
			append(owner, name, uri, "BOOLEAN " + value + "\n");
		}
	}

	public static void error(Object owner, String name, String uri, Throwable t) {
		if (enabled()) {
			String msg = String.valueOf(t.getMessage());
			int nl = msg.indexOf('\n');
			if (nl >= 0) {
				msg = msg.substring(0, nl);
			}
			if (msg.length() > 300) {
				msg = msg.substring(0, 300);
			}
			append(owner, name, uri, "ERROR " + t.getClass().getName() + ": " + msg + "\n");
		}
	}

	private static Path file(Object owner, String name, String uri) throws Exception {
		Path dir = Path.of(System.getProperty("diff.dump.dir"), owner.getClass().getName());
		Files.createDirectories(dir);
		MessageDigest md = MessageDigest.getInstance("SHA-1");
		String key = uri + "\u0000" + name;
		String hash = HexFormat.of().formatHex(md.digest(key.getBytes(StandardCharsets.UTF_8))).substring(0, 16);
		Path f = dir.resolve(hash + ".txt");
		if (!Files.exists(f)) {
			Files.writeString(f, "# " + name + "\n# " + uri + "\n", StandardCharsets.UTF_8);
		}
		return f;
	}

	private static void append(Object owner, String name, String uri, String body) {
		try {
			Files.writeString(file(owner, name, uri), body, StandardCharsets.UTF_8, StandardOpenOption.APPEND);
		} catch (Exception e) {
			throw new IllegalStateException(e);
		}
	}
}
